#include <iostream>
#include <cmath>

int main() {
    double annualInterestRate = 0.0;
    int numberOfYears = 0;
    double loanAmount = 0.0;

    if (std::cin >> annualInterestRate >> numberOfYears >> loanAmount) {
        double monthlyInterestRate = annualInterestRate / 1200.0;
        double monthlyPayment = loanAmount * monthlyInterestRate /
            (1.0 - 1.0 / std::pow(1.0 + monthlyInterestRate, numberOfYears * 12));
        double totalPayment = monthlyPayment * numberOfYears * 12;

        // Truncate to two decimal places using static_cast
        monthlyPayment = static_cast<int>(monthlyPayment * 100) / 100.0;
        totalPayment = static_cast<int>(totalPayment * 100) / 100.0;

        std::cout << "The monthly payment is " << monthlyPayment << "\n";
        std::cout << "The total payment is " << totalPayment << "\n";
    }
    return 0;
}

#include <iostream>
#include <cmath>

int main() {
    // CheckPoint 2.30: (-b + sqrt(b^2 - 4ac)) / (2a)
    double a = 1.0;
    double b = -5.0;
    double c = 6.0;

    if (std::cin >> a >> b >> c) {
        double discriminant = b * b - 4 * a * c;
        if (discriminant >= 0) {
            double root = (-b + std::sqrt(discriminant)) / (2 * a);
            std::cout << "Root: " << root << "\n";
        }
    }
    return 0;
}

#include <iostream>

int main() {
    double amount = 0.0;
    if (std::cin >> amount) {
        // Convert dollars to total cents
        int remainingAmount = static_cast<int>(amount * 100);

        // Find one dollars
        int numberOfOneDollars = remainingAmount / 100;
        remainingAmount %= 100;

        // Find quarters (25 cents)
        int numberOfQuarters = remainingAmount / 25;
        remainingAmount %= 25;

        // Find dimes (10 cents)
        int numberOfDimes = remainingAmount / 10;
        remainingAmount %= 10;

        // Find nickels (5 cents)
        int numberOfNickels = remainingAmount / 5;
        remainingAmount %= 5;

        // Remaining amount is pennies (1 cent)
        int numberOfPennies = remainingAmount;

        std::cout << "Your amount " << amount << " consists of \n";
        std::cout << "   " << numberOfOneDollars << " dollars\n";
        std::cout << "   " << numberOfQuarters << " quarters\n";
        std::cout << "   " << numberOfDimes << " dimes\n";
        std::cout << "   " << numberOfNickels << " nickels\n";
        std::cout << "   " << numberOfPennies << " pennies\n";
    }
    return 0;
}
